import{z as i,x as s,o as e,c as l,q as t,j as n,D as E,d as A,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"实验管理","description":"","frontmatter":{"title":"实验管理","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/rc2-experiment-management.md","filePath":"quant/rc2-experiment-management.md","lastUpdated":1791413859000}'),C={name:"quant/rc2-experiment-management.md"};function d(p,a,h,m,c,u){const r=s("Mermaid");return e(),l("div",null,[a[2]||(a[2]=t('<h1 id="实验管理" tabindex="-1">实验管理 <a class="header-anchor" href="#实验管理" aria-label="Permalink to &quot;实验管理&quot;">​</a></h1><div class="epigraph"><p>没有台账的四十次尝试里，最好的那一次不是发现，是抽样误差的冠军。</p><footer>—— 据 Harvey, Liu and Zhu, …and the Cross-Section of Expected Returns, Review of Financial Studies, 2016；Bailey, Borwein, López de Prado and Zhu, Notices of the AMS, 2014 整理</footer></div><p><a href="/quant/rc2-notebook-engineering">上一课</a>让一次实验经得起重启重跑。缺口随即升级：一项研究不是一次实验，是一串——今天换窗口，明天换特征，后天换 universe。一串实验若没有台账，串里最好的成绩无法解释，因为你连串里一共有多少次尝试都数不出。本课写实验管理的最小机制：每次运行登记指纹与指标，试验计数保持完整，横比口径统一。它是<a href="/quant/research-log-discipline">研究日志纪律</a>在工程上的落点。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实验管理的核心困难不在记录，在<strong>完整</strong>。手记台账漏掉的几乎全是失败的尝试：人只在成功时想留下记录。残缺台账比没有台账更会撒谎——分母 \\(N\\) 被静默缩小，分子全是赢家，于是最普通的一次运气在台账里看起来像信号。计量的后果是硬的：检验统计量要除以尝试次数打折，\\(N\\) 记不全，折价就算不出。<a href="/quant/backtest-overfitting">回测过拟合</a>的 CSCV 框架与<a href="/quant/bailey-dsr">缩水夏普</a>都假设你知道 \\(N\\)；假设落空，整条防线失效。第二个困难是<strong>可比</strong>：三周前的成绩与今天的成绩要能放在同一张表里比，前提是数据版本、切分与指标口径都没动过——而这三样恰恰是最常被顺手改掉的。</p><p><span class="marginnote">数字实例：你真实试了 40 组参数、记下 8 组「有印象的」，多重检验折价按 \\(N=8\\) 算，门槛形同虚设——而 40 次里挑最大值，纯运气也能堆出一根漂亮曲线。漏记的几乎全是输家，所以残缺台账的偏差方向恒定为高估：它不是记录不完整的中性问题，是系统性说谎。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="最小登记字段" tabindex="-1">最小登记字段 <a class="header-anchor" href="#最小登记字段" aria-label="Permalink to &quot;最小登记字段&quot;">​</a></h3><p>每次运行自动登记五项：<strong>配置指纹</strong>（配置文件哈希，改参即换指纹）、<strong>代码版本</strong>（commit 哈希）、<strong>数据版本引用</strong>（<a href="/quant/de-data-versioning">数据版本化</a>的快照 ID，不是「数据库当前状态」）、<strong>指标</strong>（预先锁定的主指标在前，完整指标在后）、<strong>产物路径</strong>。登记必须自动挂在入口命令上，不给「这次先不记」留操作空间；探索轨道自由登记，候选升格要走独立复跑——分轨规则照<a href="/quant/research-log-discipline">研究日志纪律</a>执行。</p>',9)),(e(),n(o,null,{default:E(()=>[B(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20RUN%5B%22%E5%85%A5%E5%8F%A3%E5%91%BD%E4%BB%A4%E5%90%AF%E5%8A%A8%E8%BF%90%E8%A1%8C%22%5D%20--%3E%20FP%5B%22%E6%8C%87%E7%BA%B9%EF%BC%9A%E9%85%8D%E7%BD%AE%E5%93%88%E5%B8%8C%20%2B%20commit%20%2B%20%E6%95%B0%E6%8D%AE%E7%89%88%E6%9C%AC%22%5D%0A%20%20FP%20--%3E%20LOG%5B%22%E8%87%AA%E5%8A%A8%E7%99%BB%E8%AE%B0%EF%BC%9A%E4%B8%BB%E6%8C%87%E6%A0%87%20%2B%20%E5%85%A8%E6%8C%87%E6%A0%87%20%2B%20%E4%BA%A7%E7%89%A9%22%5D%0A%20%20LOG%20--%3E%20LEDGER%5B%22%E5%8F%B0%E8%B4%A6%EF%BC%9AN%20%E4%BF%9D%E6%8C%81%E5%AE%8C%E6%95%B4%22%5D%0A%20%20LEDGER%20--%3E%20CMP%5B%22%E5%90%8C%E7%89%88%E6%9C%AC%E5%90%8C%E5%88%87%E5%88%86%E6%89%8D%E6%A8%AA%E6%AF%94%22%5D%0A%20%20CMP%20--%3E%20PROMO%7B%22%E5%80%99%E9%80%89%E5%8D%87%E6%A0%BC%22%7D%0A%20%20PROMOTE%5B%22%E7%8B%AC%E7%AB%8B%E5%A4%8D%E8%B7%91%20%2B%20%E7%8B%AC%E7%AB%8B%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20PROMO%0A%20%20PROMO%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20NEXT%5B%22%E8%BF%9B%E5%85%A5%E5%AE%9A%E6%A1%88%E6%B5%81%E7%A8%8B%22%5D%0A%20%20PROMO%20--%3E%7C%E6%9C%AA%E8%BF%87%7C%20LEDGER%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>台账真正的产出不是「找回某次实验」，是<strong>让 \\(N\\) 成为可审计的量</strong>。<a href="/quant/research-postmortem">研究复盘</a>的假设台账、<a href="/quant/fml-research-workflow">回测协议</a>的试验可数，落点都在这张表上：评审问「这组参数试过几次」，答案从台账查询来，不从记忆来。横比的机制同样由此保证：两次登记的指纹若只在配置一栏不同，差异可以归因到参数；三栏都不同，根本不许放进同一张比较表——口径漂移下的排名是在比噪声。扫描框架的落库规则（<a href="/quant/bf-param-sweep-arch">参数扫描的架构</a>）是本课在批量场景的特例：扫描的每一格都是一次运行，都要入账。</p>',2)),(e(),n(o,null,{default:E(()=>[B(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%A4%E6%AC%A1%E7%99%BB%E8%AE%B0%E8%A6%81%E6%A8%AA%E6%AF%94%22%5D%20--%3E%20B%7B%22%E6%95%B0%E6%8D%AE%E7%89%88%E6%9C%AC%E5%BC%95%E7%94%A8%E7%9B%B8%E5%90%8C%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%22%E5%90%A6%22%7C%20X%5B%22%E4%B8%8D%E5%8F%AF%E6%AF%94%20%E4%B8%8D%E8%BF%9B%E5%90%8C%E4%B8%80%E5%BC%A0%E8%A1%A8%22%5D%0A%20%20B%20--%3E%7C%22%E6%98%AF%22%7C%20C%7B%22%E5%88%87%E5%88%86%E4%B8%8E%E6%8C%87%E6%A0%87%E5%8F%A3%E5%BE%84%E7%9B%B8%E5%90%8C%EF%BC%9F%22%7D%0A%20%20C%20--%3E%7C%22%E5%90%A6%22%7C%20X%0A%20%20C%20--%3E%7C%22%E6%98%AF%22%7C%20D%7B%22%E4%BB%A3%E7%A0%81%20commit%20%E7%9B%B8%E5%90%8C%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20E%5B%22%E4%BB%85%E4%BE%9B%E5%8F%82%E8%80%83%EF%BC%9A%E5%B7%AE%E5%BC%82%E6%B7%B7%E5%85%A5%E4%BB%A3%E7%A0%81%E6%94%B9%E5%8A%A8%22%5D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20F%7B%22%E4%BB%85%E9%85%8D%E7%BD%AE%E5%93%88%E5%B8%8C%E4%B8%8D%E5%90%8C%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%22%E6%98%AF%22%7C%20G%5B%22%E5%8F%AF%E5%BD%92%E5%9B%A0%EF%BC%9A%E5%B7%AE%E5%BC%82%E6%9D%A5%E8%87%AA%E5%8F%82%E6%95%B0%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">术语翻译：「指纹」就是把一份配置压成一个短哈希串——内容改一个字符，指纹整个变样，如同人的指纹。它回答的问题是「这两次跑的是同一个东西吗」，而不是「这次跑了什么」；读懂配置仍要回到原文件，指纹只负责认出「变了」和「哪个变了」。</span></p><p>不这么做错在哪：没有自动登记的团队，半年后的典型对话是「我记得我们试过动量，好像是二十天窗口，效果还行」——没有指纹、没有 \\(N\\)、没有切分口径，这句话既不能证实也不能证伪，只能重试一遍，而重试又是一次不入账的尝试。</p><p><span class="marginnote">Harvey–Liu–Zhu 给出的口径：考虑到跨试验的多重比较，新因子的 t 统计量门槛应从 2 抬到 3。门槛抬得再高，也救不了记不全的分母——漏记的试验几乎全是失败的，这使台账的偏差方向恒定为高估。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>实验管理不判断好坏：台账记录的是「做过什么」，判据与放弃线属于研究文档与提案评审，升格决策属于委员会。它也不替代版本控制——台账引用 commit 与快照，本身不存代码与数据；引用断了（快照被删、仓库被清），台账退化为购物小票，所以引用的靶标必须落在不可变存储上；打包与盲跑的验收标准，是下一课的主题。最后，别把台账当成品排行：主指标之外的完整指标登记在案，就是为了防止「按单一指标排名」把台账用成新的过拟合装置。</p><p><span class="marginnote">常见误区：初学者容易把台账当成「策略排行榜」，按主指标降序挑第一名。实际上台账是「尝试清单」，主指标预先锁定是为了防挑挑拣拣，不是鼓励按它重排——按台账榜首直接升格，等于把 \\(N\\) 次尝试的运气冠军又送进一遍定案评审，多重检验折价被第二次忽略。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>实验管理的核心是完整性：\\(N\\) 记不全，多重检验折价失效，台账反而放大高估。</li><li>最小五字段：配置指纹、代码 commit、数据版本引用、指标（主指标预锁）、产物路径。</li><li>登记自动挂入口，不给「先不记」留操作空间；探索与候选分轨，升格走独立复跑。</li><li>横比只在同数据版本、同切分、同指标口径下进行，指纹差异决定可比性。</li><li>出处：Harvey, Liu and Zhu, <em>RFS</em>, 2016；Bailey, Borwein, López de Prado and Zhu, <em>Notices of the AMS</em>, 2014；站内<a href="/quant/research-log-discipline">研究日志纪律</a>、<a href="/quant/de-data-versioning">数据版本化</a>、<a href="/quant/backtest-overfitting">回测过拟合</a>各课。</li></ul>',8))])}const F=i(C,[["render",d]]);export{f as __pageData,F as default};
